app-assembly-export-animatic-dialog.text.source:
`${n} ${n === 1 ? "scene" : "scenes"} in script order, ${formatSeconds(
                framesToSeconds(sel.endFrame - sel.startFrame, fps),
              )}.`

`${placeholders.length} ${
            placeholders.length === 1 ? "scene" : "scenes"
          } without a 2D scene are shown as title cards (${placeholders
            .slice(0, 4)
            .map((c) => c.productionNumber ?? formatHeading(c.heading))
            .join(", ")}${placeholders.length > 4 ? " …" : ""}).`

`${audible.length} ${audible.length === 1 ? "audio clip" : "audio clips"} included in the video${
            audible.length < sounds.length
              ? ` (${sounds.length - audible.length} in muted tracks are not included)`
              : ""
          }.`

app-assembly-film-timeline.clip-block.ar.source:
`Scene ${clip.productionNumber ?? index + 1}: ${heading}, ${formatSeconds(seconds)}${
          placeholder ? ", no 2D scene" : clip.source === "film" ? ", finished film" : ""
        }${clip.transition.kind !== "cut" ? `, ${TRANSITION_LABEL[clip.transition.kind].toLowerCase()} in${clip.overlapFrames > 0 ? " with overlap" : ""}` : ""}${clip.monochrome ? ", black and white" : ""}${flags ? ", the script has changed since the material was made" : ""}`

app-assembly-film-timeline.clip-block.ti.text:
{value1} {heading}
{value3}{value4}{value5}{value6}{value7}
{value8}Double-click to open in the scene editor.

app-assembly-film-timeline.clip-block.ti.source:
`${clip.productionNumber ?? ""} ${heading}\n${formatSeconds(seconds)}${
          clip.durationKind === "estimate"
            ? " (estimated from the script)"
            : clip.durationKind === "planned"
              ? " (planned)"
              : ""
        }${placeholder ? "\nNo 2D scene yet – shown as a title card" : ""}${
          clip.edited
            ? `\nEdited: ${clip.parts.length} ${clip.parts.length === 1 ? "part" : "parts"}`
            : ""
        }${
          clip.source === "film" ? `\nFinished film: ${clip.take?.media?.fileName ?? ""}` : ""
        }\n${movable ? "Drag to move the scene. " : ""}Double-click to open in the scene editor.`

app-library-image-ai-panels.turnaround-p.source:
